$a=array('000001','Snapshot Brand','Snapshot Model','LE','White','2026','68000','Snapshot Supplier','Main warehouse','','Black','10');$b=$a;$b[0]='000002';$b[4]='Black';$c=$a;$c[0]='A000003';$c[3]='XLE';$c[5]='2025';$c[6]='70000';
